import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    total_opp_c = sum(1 for x in opp if x == 'C')
    total_opp_d = n - total_opp_c
    last_opp = opp[-1]
    last_me = me[-1]

    # Last round: always defect unless we need to preserve a massive
    # cooperative relationship we can't change anyway. Defect is dominant.
    if n == 100:
        return 'D'

    # Very end-game: defect, but only when it's safe (opponent not likely
    # to be a harsh retaliator we still need points from).
    if n >= 96:
        # If opponent has been nearly always cooperative, exploit.
        if total_opp_d <= 1:
            return 'D'
        # If opponent has been mostly cooperative, defect too.
        if total_opp_c * 100 >= n * 60:
            return 'D'
        # Against a defector, defect.
        if total_opp_d * 100 >= n * 60:
            return 'D'
        return 'C'

    # Detect pure cooperator early; exploit moderately but keep them happy.
    if total_opp_d == 0:
        if n >= 8 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Detect pure defector; defect.
    if total_opp_c == 0:
        return 'D'

    # Recent window stats
    win = history[-12:] if n >= 12 else history
    wlen = len(win)
    recent_opp_c = sum(1 for a, b in win if b == 'C')
    recent_opp_d = wlen - recent_opp_c
    recent_me_c = sum(1 for a, b in win if a == 'C')

    # Count opponent defection streaks at the tail.
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak_d += 1
        else:
            break
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            streak_c += 1
        else:
            break

    # Exploit an opponent who never retaliates: measure how often our
    # defections were answered by continued cooperation.
    if n >= 15:
        if last_me == 'D' and last_opp == 'C':
            # Count how many times we defected and they cooperated next.
            forgive_count = 0
            defection_count = 0
            for i in range(n - 1):
                if me[i] == 'D' and me[i + 1] == 'D':
                    defection_count += 1
                    if opp[i + 1] == 'C':
                        forgive_count += 1
            # If opponent rarely punishes our defections, exploit hard.
            if defection_count >= 3 and forgive_count * 100 >= defection_count * 70:
                if rng.random() < 0.45:
                    return 'D'
                return 'C'

    # If opponent just defected:
    if last_opp == 'D':
        # Very cooperative opponent who slipped: forgive once.
        if total_opp_c * 100 >= n * 80 and streak_d <= 1:
            return 'C'
        # Long punishment? Break it to try to restore cooperation.
        if streak_d >= 4 and recent_me_c >= 3:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Standard tit-for-tat retaliation, with some forgiveness.
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    # If they've been very cooperative, occasionally defect to exploit.
    if total_opp_c * 100 >= n * 85 and n >= 20:
        # Probe pattern to avoid being detected as a permanent defector.
        if streak_c >= 3 and rng.random() < 0.18:
            return 'D'
        return 'C'

    # If we just defected and they still cooperate, keep going occasionally.
    if last_me == 'D' and last_opp == 'C':
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # If our recent behavior has been too cooperative relative to a
    # moderately defecting opponent, tighten up.
    if recent_opp_d >= 3 and recent_me_c >= 4:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Occasional random probe to test opponents in the middle game.
    if n % 11 == 7 and n > 20 and n < 90:
        if total_opp_c * 100 >= n * 70:
            if rng.random() < 0.35:
                return 'D'

    # Occasional forgiveness probe after mutual defection.
    if last_me == 'D' and last_opp == 'D':
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    return 'C'
